const char *PEGRuleIdToString(PEGRuleId rule_id) {
	auto index = static_cast<uint32_t>(rule_id);
	if (index == 0 || index >= static_cast<uint32_t>(PEGRuleId::BUILTIN_COUNT)) {
		return nullptr;
	}
	return PEG_RULE_NAMES[index];
}

PEGRuleId PEGRuleIdFromString(const string &rule_name) {
	static const case_insensitive_map_t<PEGRuleId> lookup = [] {
		case_insensitive_map_t<PEGRuleId> result;
		for (uint32_t i = 1; i < static_cast<uint32_t>(PEGRuleId::BUILTIN_COUNT); i++) {
			result.emplace(PEG_RULE_NAMES[i], static_cast<PEGRuleId>(i));
		}
		return result;
	}();
	auto entry = lookup.find(rule_name);
	return entry == lookup.end() ? PEGRuleId::INVALID : entry->second;
}

